/// The paired device behind a request's bearer token, or a
/// browser's cookie named for this host when there is no bearer,
/// seen now; or the refusal, which says nothing of the host.
fn authenticate(&mut self, request: &RemoteRequest) -> Result<PairedDevice, RemoteReply> {
    let cookie = || {
        let name = remote::token_cookie_name(self.core.identity()?.server_id);
        remote::cookie_value(request.cookie.as_deref()?, &name).map(str::to_owned)
    };
    let by_cookie = request.bearer.is_none();
    let Some(token) = request.bearer.clone().or_else(cookie) else {
        return Err(self.refuse(
            request,
            401,
            "unauthorized",
            "pair this device first",
            false,
        ));
    };
    let Some(device) = self
        .core
        .device_by_token(&remote::token_sha256(&token))
        .cloned()
    else {
        return Err(self.refuse(
            request,
            401,
            "unauthorized",
            "the token is not known; pair again",
            false,
        ));
    };
    // A browser sends its cookie with whatever a page on any port
    // of this address asks for, so a write or an upgrade made by
    // cookie alone must come from this host's own page. A native
    // client sends its bearer and no `Origin`.
    let writes = request.method != "GET" || request.upgrade.is_some();
    if by_cookie && writes && !same_origin(request) {
        return Err(self.refuse(
            request,
            403,
            "origin",
            "a write by cookie must come from this host's page",
            false,
        ));
    }
    self.dispatch_inner(AppAction::DeviceSeen(device.id));
    Ok(device)
}

